import{_ as t,o as e,c as d,a2 as o}from"./chunks/framework.DoCD98hS.js";const p=JSON.parse('{"title":"Fantastic Admin · 基础库、Fa 组件与模板","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/fan.md","filePath":"modules/catalog/fan.md","lastUpdated":null}'),l={name:"modules/catalog/fan.md"};function r(n,a,c,i,s,h){return e(),d("div",null,[...a[0]||(a[0]=[o('<h1 id="fantastic-admin-·-基础库、fa-组件与模板" tabindex="-1">Fantastic Admin · 基础库、Fa 组件与模板 <a class="header-anchor" href="#fantastic-admin-·-基础库、fa-组件与模板" aria-label="Permalink to &quot;Fantastic Admin · 基础库、Fa 组件与模板&quot;">​</a></h1><p>将 Fan 的 libs、comps 和 Element Plus / Reka UI 两个模板集中介绍，公共接入步骤只维护一份。</p><div class="info custom-block"><p class="custom-block-title">文档骨架</p><p>先占位目录与已核对的代表性能力，不是完整 API 清单。参数、完整示例和逐文件改造细节待本轮实现定稿后补充；待补项不表示已实现或已发布。</p></div><h2 id="包范围" tabindex="-1">包范围 <a class="header-anchor" href="#包范围" aria-label="Permalink to &quot;包范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包名</th><th>职责</th></tr></thead><tbody><tr><td><code>@melt-js/libs-fan</code></td><td>composables、设置、主题、快捷键等普通基础库</td></tr><tr><td><code>@melt-js/comps-fan</code></td><td>Fa 系列远程组件、hooks 与 examples</td></tr><tr><td><code>@melt-js/tpl-vue3-admin-ele-fan</code></td><td>Element Plus 后台宿主</td></tr><tr><td><code>@melt-js/tpl-vue3-admin-reka-fan</code></td><td>Reka UI 完整示例宿主</td></tr></tbody></table><h2 id="在线演示" tabindex="-1">在线演示 <a class="header-anchor" href="#在线演示" aria-label="Permalink to &quot;在线演示&quot;">​</a></h2><p>链接按各包 <code>package.json</code> 的 <code>unpkg</code> 入口生成，打开 npm 已发布的默认版本；页面内容随包发布更新。</p><table tabindex="0"><thead><tr><th>模板 / 示例</th><th>unpkg 演示</th></tr></thead><tbody><tr><td><code>tpl-vue3-admin-ele-fan</code></td><td><a href="https://unpkg.com/@melt-js/tpl-vue3-admin-ele-fan/dist/index.html" target="_blank" rel="noreferrer">打开演示</a></td></tr><tr><td><code>tpl-vue3-admin-reka-fan</code></td><td><a href="https://unpkg.com/@melt-js/tpl-vue3-admin-reka-fan/dist/index.html" target="_blank" rel="noreferrer">打开演示</a></td></tr></tbody></table><h2 id="提供的方法与工具" tabindex="-1">提供的方法与工具 <a class="header-anchor" href="#提供的方法与工具" aria-label="Permalink to &quot;提供的方法与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口 / 能力</th><th>用途</th></tr></thead><tbody><tr><td>libs：<code>usePagination</code> 等 composables</td><td>通过公开子路径组织，完整清单待补</td></tr><tr><td>comps：<code>useFaToast</code> / <code>useFaDrawer</code> / <code>useFaModal</code></td><td>消息、抽屉与弹层 hooks</td></tr></tbody></table><h2 id="提供的组件" tabindex="-1">提供的组件 <a class="header-anchor" href="#提供的组件" aria-label="Permalink to &quot;提供的组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件 / 分组</th><th>用途</th></tr></thead><tbody><tr><td><code>FaButton</code> / <code>FaTable</code> / <code>FaForm</code> / <code>FaTabs</code></td><td>基础交互与数据展示</td></tr><tr><td><code>examples</code></td><td>组件示例集合，具体分类待补</td></tr></tbody></table><h2 id="接入骨架" tabindex="-1">接入骨架 <a class="header-anchor" href="#接入骨架" aria-label="Permalink to &quot;接入骨架&quot;">​</a></h2><p><code>libs-fan</code> 按普通依赖使用，<code>comps-fan</code> 预加载后从包根具名使用。两种模板的 UI 差异在此补表，不复制两套接入说明。</p><h2 id="模板简介" tabindex="-1">模板简介 <a class="header-anchor" href="#模板简介" aria-label="Permalink to &quot;模板简介&quot;">​</a></h2><p>两个模板均属 Fantastic-admin 体系，公共基础能力归 <code>libs-fan</code>、公共 Fa 组件归 <code>comps-fan</code>，页面与业务编排保留在模板。</p><h2 id="从原开源模板快速接入" tabindex="-1">从原开源模板快速接入 <a class="header-anchor" href="#从原开源模板快速接入" aria-label="Permalink to &quot;从原开源模板快速接入&quot;">​</a></h2><p>以下先列改造顺序，具体文件、配置和代码差异在实现定稿后补齐。</p><ol><li>将原分散基础模块引用改为 <code>libs-fan</code> 的公开子路径，公共 Fa 组件改为 <code>comps-fan</code>。</li><li>main 共享 Vue、设置宿主雪碧图地址并预加载组件，再动态进入 loadApp。</li><li>loadApp 注册全局 Fa 组件并完成应用、路由初始化；自动导入 hooks 指向包根。</li><li>保留模板 loading，等待 ready；组件联调时显式配置本地地址。</li></ol><h2 id="待补内容" tabindex="-1">待补内容 <a class="header-anchor" href="#待补内容" aria-label="Permalink to &quot;待补内容&quot;">​</a></h2><ul><li>[ ] 补 libs 子路径和 hooks 完整清单。</li><li>[ ] 补 Fa 组件分类、examples 索引和 props / 事件。</li><li>[ ] 补两模板差异、资源路径与逐文件改造表。</li></ul>',21)])])}const b=t(l,[["render",r]]);export{p as __pageData,b as default};
